previewCss:
.darma-loader-darma-b9-flip-tiles-grid { --accent: var(--loader-color, #8b5cf6); --accent-2: var(--loader-secondary-color, #ec4899); width: var(--loader-size, 76px); height: var(--loader-size, 76px); display: grid; grid-template-columns: repeat(3, 1fr); gap: 9%; perspective: 600px; }
.darma-loader-darma-b9-flip-tiles-grid span { width: 100%; aspect-ratio: 1; background: linear-gradient(135deg, var(--accent), var(--accent-2)); border-radius: 16%; animation: darma-loader-darma-b9-flip-tiles-grid-flip calc(var(--loader-speed, 1s) * 2) ease-in-out infinite; }
.darma-loader-darma-b9-flip-tiles-grid span:nth-child(1) { animation-delay: 0s; }
.darma-loader-darma-b9-flip-tiles-grid span:nth-child(2), .darma-loader-darma-b9-flip-tiles-grid span:nth-child(4) { animation-delay: calc(var(--loader-speed, 1s) * .14); }
.darma-loader-darma-b9-flip-tiles-grid span:nth-child(3), .darma-loader-darma-b9-flip-tiles-grid span:nth-child(5), .darma-loader-darma-b9-flip-tiles-grid span:nth-child(7) { animation-delay: calc(var(--loader-speed, 1s) * .28); }
.darma-loader-darma-b9-flip-tiles-grid span:nth-child(6), .darma-loader-darma-b9-flip-tiles-grid span:nth-child(8) { animation-delay: calc(var(--loader-speed, 1s) * .42); }
.darma-loader-darma-b9-flip-tiles-grid span:nth-child(9) { animation-delay: calc(var(--loader-speed, 1s) * .56); }
@keyframes darma-loader-darma-b9-flip-tiles-grid-flip { 0%, 100% { transform: rotateY(0deg); } 50% { transform: rotateY(180deg); } }

